		/* P3 anchored floats: the portaled MenuSurface panel (search pickers) —
		   one sheet so float material never mixes with panel css. */
		export const floatCss = `.dp_floatPanel{min-width:200px;max-width:280px;padding:4px;display:flex;flex-direction:column;gap:4px;overflow:auto}`;
		export const cssTagId = "dsh-pulse/pulse.css";
		/** Build stamp, written on the injected style tag and shown in the panel
		 *  header. The harness serves plugin bytes under `?rev=<rev>` with a
		 *  one-year `immutable` cache, so "which revision is on screen" must be
		 *  answerable without guessing — and a re-executed bundle (HMR swap)
		 *  must update the stylesheet instead of leaving the first one in place. */
		export const DP_BUILD = "0.6.0";
		if (typeof document !== "undefined") {
			let tag = document.querySelector("style[data-plugin-css=" + JSON.stringify(cssTagId) + "]");
			if (tag === null) {
				tag = document.createElement("style");
				tag.setAttribute("data-plugin-css", cssTagId);
				document.head.append(tag);
			}
			tag.setAttribute("data-plugin-css-rev", DP_BUILD);
			tag.textContent = css + themeCss + rowCss + chartCss + quotaCss + floatCss;
		}
